#!/usr/bin/env node
// Compiles ADR 0099's fixture schema on the HOST and writes it where the app bundles it.
//
// The device cannot do this itself: `glib-compile-schemas` is a binary the GI payload does not carry
// (it holds the GLib/GObject/Gio/GIRepository typelibs and libraries, no tools). `Gio.Settings`
// needs the compiled form, so the bytes travel inside the bundle as base64 and `app/specs/settings.ts`
// writes them to a directory `GSETTINGS_SCHEMA_DIR` can point at. The output is gitignored and
// regenerated by `run-on-device.mjs` before every bundle; compiled bytes are never compared across
// GLib versions, only loaded by the GLib that ships in the APK.
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { FIXTURE_SCHEMA, FIXTURE_SCHEMA_XML } from '@gjsify/app-settings/conformance';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const dir = mkdtempSync(join(tmpdir(), 'gjsify-gschemas-'));
try {
    writeFileSync(join(dir, `${FIXTURE_SCHEMA.id}.gschema.xml`), FIXTURE_SCHEMA_XML);
    const compiled = spawnSync('glib-compile-schemas', [dir], { stdio: 'inherit' });
    if (compiled.status !== 0) {
        console.error('glib-compile-schemas failed (is it installed? it ships with libglib2.0-bin / glib2-devel).');
        process.exit(1);
    }
    const base64 = readFileSync(join(dir, 'gschemas.compiled')).toString('base64');
    writeFileSync(
        join(root, 'app', 'specs', 'gschemas.generated.ts'),
        `// GENERATED by scripts/compile-schemas.mjs — do not edit, do not commit.\n` +
            `export const gschemasCompiledBase64 = '${base64}';\n`,
    );
    console.log(`[ns-gi] compiled ${FIXTURE_SCHEMA.id} (${base64.length} base64 chars)`);
} finally {
    rmSync(dir, { recursive: true, force: true });
}
